from pathlib import Path
import json,re
r=Path(__file__).resolve().parent
blocks=json.loads((r/'zh_blocks.json').read_text())
translations={}
def T(i,s):
    maths=re.findall(r'\$[^$\n]+\$',blocks[i]['text'])
